class Solution {
public:
    int numberOfSubstrings(string s) {
        int n = s.size();
        vector<int> zero_pos;
        for (int i = 0; i < n; ++i) {
            if (s[i] == '0') {
                zero_pos.push_back(i);
            }
        }
        zero_pos.push_back(n);

        int ans = 0;
        int z_idx = 0;

        for (int i = 0; i < n; ++i) {
            while (z_idx < (int)zero_pos.size() - 1 && zero_pos[z_idx] < i) {
                z_idx++;
            }
            int first_zero = zero_pos[z_idx];
            ans += first_zero - i;

            int k = 1;
            while (z_idx + k - 1 < (int)zero_pos.size() - 1) {
                int cur_z = k;
                if (cur_z * cur_z + cur_z > n - i) {
                    break;
                }
                int p = zero_pos[z_idx + k - 1];
                int next_p = zero_pos[z_idx + k];
                int min_len = cur_z * cur_z + cur_z;
                int start_j = max(p, i + min_len - 1);
                if (next_p > start_j) {
                    ans += next_p - start_j;
                }
                k++;
            }
        }
        return ans;
    }
};

class Solution {
    public int numberOfSubstrings(String s) {
        int n = s.length();
        List<Integer> zeroPos = new ArrayList<>();
        for (int i = 0; i < n; ++i) {
            if (s.charAt(i) == '0') {
                zeroPos.add(i);
            }
        }
        zeroPos.add(n);

        int ans = 0;
        int zIdx = 0;

        for (int i = 0; i < n; ++i) {
            while (zIdx < zeroPos.size() - 1 && zeroPos.get(zIdx) < i) {
                zIdx++;
            }
            int firstZero = zeroPos.get(zIdx);
            ans += firstZero - i;

            int k = 1;
            while (zIdx + k - 1 < zeroPos.size() - 1) {
                int curZ = k;
                if (curZ * curZ + curZ > n - i) {
                    break;
                }
                int p = zeroPos.get(zIdx + k - 1);
                int nextP = zeroPos.get(zIdx + k);
                int minLen = curZ * curZ + curZ;
                int startJ = Math.max(p, i + minLen - 1);
                if (nextP > startJ) {
                    ans += nextP - startJ;
                }
                k++;
            }
        }
        return ans;
    }
}

